203	                    final UnivariateRealFunction f = new UnivariateRealFunction() {
204	                        public double value(final double t) throws FunctionEvaluationException {
205	                            try {
206	                                interpolator.setInterpolatedTime(t);
207	                                return handler.g(t, interpolator.getInterpolatedState());
