219	                    if ((Math.abs(root - ta) <= convergence) &&
220	                         (Math.abs(root - previousEventTime) <= convergence)) {
221	                        // we have either found nothing or found (again ?) a past event, we simply ignore it
222	                        ta = tb;
223	                        ga = gb;
