229	                            // found during a previous call for a step that was
230	                            // rejected, this step must now be accepted since it
231	                            // properly ends exactly at the event occurrence
232	                            return false;
233	                        }
234	                        // either we were not waiting for the event or it has
235	                        // moved in such a way the step cannot be accepted
236	                        pendingEvent = true;
237	                        return true;
238	                    }
239	
240	                } else {
241	                    // no sign change: there is no event for now
242	                    ta = tb;
243	                    ga = gb;
244	                }
245	
246	            }
247	
248	            // no event during the whole step
249	            pendingEvent     = false;
250	            pendingEventTime = Double.NaN;
251	            return false;
252	
253	        } catch (FunctionEvaluationException e) {
254	            final Throwable cause = e.getCause();
255	            if ((cause != null) && (cause instanceof DerivativeException)) {
256	                throw (DerivativeException) cause;
257	            } else if ((cause != null) && (cause instanceof EventException)) {
